  CONSTRAINT `fk_css_sale` FOREIGN KEY (`cooperative_sale_id`) REFERENCES `cooperative_sales` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- crop_fields
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `crop_fields`;
CREATE TABLE IF NOT EXISTS `crop_fields` (
  `id` varchar(40) NOT NULL,
  `farm_id` varchar(40) NOT NULL,
  `field_id` varchar(40) NOT NULL,
  `crop_type_id` varchar(40) NOT NULL,
  `variety` varchar(120) NOT NULL DEFAULT '',
  `area_planted` decimal(12,3) NOT NULL DEFAULT 0.000,
  `season` varchar(60) NOT NULL DEFAULT '',
  `planting_date` date NOT NULL,
  `expected_harvest_date` date NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'Active',
  `is_archived` tinyint(1) NOT NULL DEFAULT 0,
  `archived_at` datetime DEFAULT NULL,
  `archived_reason` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cf_farm` (`farm_id`),
  KEY `idx_cf_field` (`field_id`),
  KEY `idx_cf_crop_type` (`crop_type_id`),
  KEY `idx_cf_season` (`farm_id`,`season`),
  KEY `idx_cf_active` (`farm_id`,`is_archived`,`status`),
  CONSTRAINT `fk_cf_crop_type` FOREIGN KEY (`crop_type_id`) REFERENCES `crop_types` (`id`),
  CONSTRAINT `fk_cf_farm` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cf_field` FOREIGN KEY (`field_id`) REFERENCES `fields` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- crop_incidents
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `crop_incidents`;
CREATE TABLE IF NOT EXISTS `crop_incidents` (
  `id` varchar(40) NOT NULL,
  `farm_id` varchar(40) NOT NULL,
  `crop_field_id` varchar(40) NOT NULL,
  `type` varchar(20) NOT NULL DEFAULT 'pest',
  `description` varchar(500) NOT NULL,
  `severity` varchar(20) NOT NULL DEFAULT 'moderate',
  `status` varchar(20) NOT NULL DEFAULT 'open',
  `reported_date` date NOT NULL,
  `treatment_notes` varchar(1000) DEFAULT NULL,
  `referred_to` varchar(160) DEFAULT NULL,
  `created_by_id` varchar(40) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ci_farm` (`farm_id`,`status`),
  KEY `idx_ci_crop_field` (`crop_field_id`),
  KEY `idx_ci_farm_type_date` (`farm_id`,`type`,`reported_date`),
  KEY `fk_ci_user` (`created_by_id`),
  CONSTRAINT `fk_ci_crop_field` FOREIGN KEY (`crop_field_id`) REFERENCES `crop_fields` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ci_farm` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ci_user` FOREIGN KEY (`created_by_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- crop_types
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `crop_types`;
CREATE TABLE IF NOT EXISTS `crop_types` (
  `id` varchar(40) NOT NULL,
  `farm_id` varchar(40) DEFAULT NULL,
  `name` varchar(120) NOT NULL,
  `is_custom` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_crop_types_scope_name` (`farm_id`,`name`),
  KEY `idx_crop_types_farm` (`farm_id`),
  CONSTRAINT `fk_crop_types_farm` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- demo_bookings
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `demo_bookings`;
CREATE TABLE IF NOT EXISTS `demo_bookings` (
  `id` varchar(40) NOT NULL,
  `name` varchar(160) NOT NULL,
  `email` varchar(190) NOT NULL,
  `farm` varchar(160) NOT NULL DEFAULT '',
  `message` text DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `notes` text DEFAULT NULL,
  `booked_for` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_demo_status` (`status`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- employees
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `employees`;
CREATE TABLE IF NOT EXISTS `employees` (
  `id` varchar(40) NOT NULL,
  `farm_id` varchar(40) NOT NULL,
  `name` varchar(120) NOT NULL,
  `role` varchar(80) NOT NULL DEFAULT '',
  `pay_rate` decimal(12,2) NOT NULL DEFAULT 0.00,
  `pay_rate_unit` varchar(20) NOT NULL DEFAULT 'day',
  `phone` varchar(40) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_employees_farm` (`farm_id`,`is_active`),
  CONSTRAINT `fk_employees_farm` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- equipment
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `equipment`;
CREATE TABLE IF NOT EXISTS `equipment` (
  `id` varchar(40) NOT NULL,
  `farm_id` varchar(40) NOT NULL,
  `name` varchar(160) NOT NULL,
  `category` varchar(40) NOT NULL DEFAULT 'other',
  `status` varchar(20) NOT NULL DEFAULT 'active',
  `acquisition_date` date DEFAULT NULL,
  `acquisition_cost` decimal(12,2) DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_eq_farm` (`farm_id`,`status`),
  CONSTRAINT `fk_eq_farm` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- equipment_maintenance_logs
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `equipment_maintenance_logs`;
CREATE TABLE IF NOT EXISTS `equipment_maintenance_logs` (
  `id` varchar(40) NOT NULL,
  `farm_id` varchar(40) NOT NULL,
  `equipment_id` varchar(40) NOT NULL,
  `date` date NOT NULL,
  `description` varchar(255) NOT NULL,
  `cost` decimal(12,2) NOT NULL DEFAULT 0.00,
  `hours_used` decimal(10,1) DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_eml_equipment` (`equipment_id`),
  KEY `idx_eml_farm` (`farm_id`),
  CONSTRAINT `fk_eml_equipment` FOREIGN KEY (`equipment_id`) REFERENCES `equipment` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- farms
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `farms`;
CREATE TABLE IF NOT EXISTS `farms` (
  `id` varchar(40) NOT NULL,
  `name` varchar(160) NOT NULL,
  `location` varchar(160) NOT NULL DEFAULT '',
  `location_lat` double DEFAULT NULL,
  `location_lng` double DEFAULT NULL,
  `owner_name` varchar(120) DEFAULT NULL,
  `user_id` varchar(40) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_farms_user` (`user_id`),
  CONSTRAINT `fk_farms_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- farm_activities
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `farm_activities`;
CREATE TABLE IF NOT EXISTS `farm_activities` (
  `id` varchar(40) NOT NULL,
  `farm_id` varchar(40) NOT NULL,
  `field_id` varchar(40) NOT NULL,
  `crop_field_id` varchar(40) DEFAULT NULL,
  `activity_type` varchar(80) NOT NULL,
  `date` date NOT NULL,
  `notes` text DEFAULT NULL,
  `responsible_person_name` varchar(120) DEFAULT NULL,
  `responsible_employee_id` varchar(40) DEFAULT NULL,
  `created_by_id` varchar(40) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_fa_farm_date` (`farm_id`,`date`),
  KEY `idx_fa_field` (`field_id`),
  KEY `idx_fa_crop_field` (`crop_field_id`),
  KEY `idx_fa_type` (`farm_id`,`activity_type`),
  KEY `fk_fa_employee` (`responsible_employee_id`),
  KEY `fk_fa_creator` (`created_by_id`),
  CONSTRAINT `fk_fa_creator` FOREIGN KEY (`created_by_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_fa_crop_field` FOREIGN KEY (`crop_field_id`) REFERENCES `crop_fields` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_fa_employee` FOREIGN KEY (`responsible_employee_id`) REFERENCES `employees` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_fa_farm` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_fa_field` FOREIGN KEY (`field_id`) REFERENCES `fields` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
