  `created_at` datetime NOT NULL,
  `sent_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_mail_queue_status` (`status`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- market_prices
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `market_prices`;
CREATE TABLE IF NOT EXISTS `market_prices` (
  `id` varchar(40) NOT NULL,
  `crop_name` varchar(120) NOT NULL,
  `variety` varchar(120) DEFAULT NULL,
  `unit` varchar(20) NOT NULL DEFAULT 'kg',
  `price_min` decimal(12,2) NOT NULL DEFAULT 0.00,
  `price_max` decimal(12,2) NOT NULL DEFAULT 0.00,
  `price_avg` decimal(12,2) NOT NULL DEFAULT 0.00,
  `market` varchar(120) NOT NULL DEFAULT '',
  `region` varchar(120) NOT NULL DEFAULT '',
  `currency` varchar(3) NOT NULL DEFAULT 'MWK',
  `season` varchar(60) DEFAULT NULL,
  `recorded_at` datetime NOT NULL,
  `source` varchar(60) NOT NULL DEFAULT 'ADMARC',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_mp_crop` (`crop_name`,`is_active`),
  KEY `idx_mp_recorded` (`recorded_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- market_price_feed_state
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `market_price_feed_state`;
CREATE TABLE IF NOT EXISTS `market_price_feed_state` (
  `id` varchar(10) NOT NULL,
  `last_checked_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- market_price_updates
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `market_price_updates`;
CREATE TABLE IF NOT EXISTS `market_price_updates` (
  `id` varchar(40) NOT NULL,
  `existing_price_id` varchar(40) DEFAULT NULL,
  `crop_name` varchar(120) NOT NULL,
  `variety` varchar(120) DEFAULT NULL,
  `unit` varchar(20) NOT NULL DEFAULT 'kg',
  `price_min` decimal(12,2) NOT NULL DEFAULT 0.00,
  `price_max` decimal(12,2) NOT NULL DEFAULT 0.00,
  `price_avg` decimal(12,2) NOT NULL DEFAULT 0.00,
  `market` varchar(120) NOT NULL DEFAULT '',
  `region` varchar(120) NOT NULL DEFAULT '',
  `currency` varchar(3) NOT NULL DEFAULT 'MWK',
  `recorded_at` datetime NOT NULL,
  `source` varchar(60) NOT NULL DEFAULT 'WFP',
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `fetched_at` datetime NOT NULL,
  `reviewed_by` varchar(40) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_mpu_pending_slot` (`crop_name`,`region`,`source`,`status`),
  KEY `idx_mpu_status` (`status`),
  KEY `fk_mpu_existing` (`existing_price_id`),
  KEY `fk_mpu_reviewer` (`reviewed_by`),
  CONSTRAINT `fk_mpu_existing` FOREIGN KEY (`existing_price_id`) REFERENCES `market_prices` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_mpu_reviewer` FOREIGN KEY (`reviewed_by`) REFERENCES `admin_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- notifications
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `notifications`;
CREATE TABLE IF NOT EXISTS `notifications` (
  `id` varchar(40) NOT NULL,
  `user_id` varchar(40) NOT NULL,
  `farm_id` varchar(40) NOT NULL,
  `type` varchar(40) NOT NULL,
  `dedupe_key` varchar(160) NOT NULL,
  `title` varchar(160) NOT NULL,
  `message` varchar(500) NOT NULL,
  `is_read` tinyint(1) NOT NULL DEFAULT 0,
  `link` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_notif_dedupe` (`user_id`,`dedupe_key`),
  KEY `idx_notif_user` (`user_id`,`is_read`,`created_at`),
  KEY `fk_notif_farm` (`farm_id`),
  CONSTRAINT `fk_notif_farm` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_notif_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- overhead_expenses
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `overhead_expenses`;
CREATE TABLE IF NOT EXISTS `overhead_expenses` (
  `id` varchar(40) NOT NULL,
  `farm_id` varchar(40) NOT NULL,
  `description` varchar(200) NOT NULL,
  `category` varchar(40) NOT NULL DEFAULT 'Other',
  `amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `date` date NOT NULL,
  `recurring` tinyint(1) NOT NULL DEFAULT 0,
  `notes` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_oh_farm_date` (`farm_id`,`date`),
  CONSTRAINT `fk_oh_farm` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- payments
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `payments`;
CREATE TABLE IF NOT EXISTS `payments` (
  `id` varchar(40) NOT NULL,
  `subscription_id` varchar(40) NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `currency` varchar(3) NOT NULL DEFAULT 'MWK',
  `status` varchar(20) NOT NULL,
  `method` varchar(30) NOT NULL,
  `reference` varchar(120) DEFAULT NULL,
  `provider_transaction_id` varchar(120) DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  `paid_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `created_by_admin_id` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_payments_provider_txn` (`provider_transaction_id`),
  KEY `idx_payments_subscription` (`subscription_id`),
  CONSTRAINT `fk_payments_subscription` FOREIGN KEY (`subscription_id`) REFERENCES `subscriptions` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- produce_storage
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `produce_storage`;
CREATE TABLE IF NOT EXISTS `produce_storage` (
  `id` varchar(40) NOT NULL,
  `farm_id` varchar(40) NOT NULL,
  `harvest_yield_id` varchar(40) NOT NULL,
  `storage_location` varchar(160) DEFAULT NULL,
  `drying_method` varchar(120) DEFAULT NULL,
  `drying_date` date DEFAULT NULL,
  `quality_grade` varchar(20) DEFAULT NULL,
  `expected_loss_qty` decimal(14,3) DEFAULT NULL,
  `loss_reason` varchar(255) DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_ps_harvest` (`harvest_yield_id`),
  KEY `idx_ps_farm` (`farm_id`),
  CONSTRAINT `fk_ps_farm` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ps_harvest` FOREIGN KEY (`harvest_yield_id`) REFERENCES `harvest_yields` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- rate_limits
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `rate_limits`;
CREATE TABLE IF NOT EXISTS `rate_limits` (
  `bucket` varchar(64) NOT NULL,
  `attempts` int(10) unsigned NOT NULL DEFAULT 0,
  `expires_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`bucket`),
  KEY `idx_rate_limits_expires` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- report_share_links
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `report_share_links`;
CREATE TABLE IF NOT EXISTS `report_share_links` (
  `id` varchar(40) NOT NULL,
  `farm_id` varchar(40) NOT NULL,
  `pack_type` varchar(20) NOT NULL,
  `token_hash` char(64) NOT NULL,
  `created_by_id` varchar(40) NOT NULL,
  `expires_at` datetime NOT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `last_viewed_at` datetime DEFAULT NULL,
  `view_count` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_rsl_hash` (`token_hash`),
  KEY `idx_rsl_farm` (`farm_id`),
  KEY `fk_rsl_user` (`created_by_id`),
  CONSTRAINT `fk_rsl_farm` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_rsl_user` FOREIGN KEY (`created_by_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- saved_reports
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `saved_reports`;
CREATE TABLE IF NOT EXISTS `saved_reports` (
  `id` varchar(40) NOT NULL,
  `farm_id` varchar(40) NOT NULL,
  `user_id` varchar(40) NOT NULL,
  `name` varchar(120) NOT NULL,
  `config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`config`)),
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sr_farm` (`farm_id`),
  KEY `fk_sr_user` (`user_id`),
  CONSTRAINT `fk_sr_farm` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_sr_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- sessions
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `sessions`;
CREATE TABLE IF NOT EXISTS `sessions` (
  `id` varchar(64) NOT NULL,
  `user_id` varchar(40) DEFAULT NULL,
  `admin_id` varchar(40) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` varchar(255) DEFAULT NULL,
  `payload` mediumtext NOT NULL,
  `last_activity` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sessions_last_activity` (`last_activity`),
  KEY `idx_sessions_user` (`user_id`),
  KEY `idx_sessions_admin` (`admin_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- site_content
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `site_content`;
CREATE TABLE IF NOT EXISTS `site_content` (
  `key` varchar(80) NOT NULL,
  `value` text NOT NULL,
  `type` varchar(20) NOT NULL DEFAULT 'text',
  `group` varchar(40) NOT NULL DEFAULT 'general',
  `label` varchar(160) DEFAULT NULL,
  `updated_at` datetime NOT NULL,
  `updated_by` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- subscriptions
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `subscriptions`;
CREATE TABLE IF NOT EXISTS `subscriptions` (
  `id` varchar(40) NOT NULL,
  `user_id` varchar(40) NOT NULL,
  `tier_id` varchar(40) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'active',
  `billing_cycle` varchar(20) NOT NULL DEFAULT 'monthly',
  `start_date` datetime NOT NULL,
  `end_date` datetime DEFAULT NULL,
  `trial_ends_at` datetime DEFAULT NULL,
  `provider` varchar(20) DEFAULT NULL,
  `provider_subscription_id` varchar(120) DEFAULT NULL,
  `activation_token` varchar(80) DEFAULT NULL,
  `activated_at` datetime DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_subscriptions_user` (`user_id`),
  UNIQUE KEY `uniq_subscriptions_provider` (`provider_subscription_id`),
  UNIQUE KEY `uniq_subscriptions_acttoken` (`activation_token`),
  KEY `idx_subscriptions_tier` (`tier_id`),
  CONSTRAINT `fk_subscriptions_tier` FOREIGN KEY (`tier_id`) REFERENCES `subscription_tiers` (`id`),
  CONSTRAINT `fk_subscriptions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- subscription_tiers
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `subscription_tiers`;
CREATE TABLE IF NOT EXISTS `subscription_tiers` (
  `id` varchar(40) NOT NULL,
  `name` varchar(80) NOT NULL,
  `description` varchar(255) NOT NULL DEFAULT '',
  `currency` varchar(3) NOT NULL DEFAULT 'MWK',
  `price_monthly` decimal(12,2) NOT NULL DEFAULT 0.00,
  `price_annual` decimal(12,2) DEFAULT NULL,
  `price_lifetime` decimal(12,2) DEFAULT NULL,
  `audience` varchar(120) DEFAULT NULL,
  `cta_label` varchar(80) DEFAULT NULL,
  `cta_href` varchar(255) DEFAULT NULL,
  `offer_items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`offer_items`)),
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_public` tinyint(1) NOT NULL DEFAULT 1,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `max_fields` int(11) NOT NULL DEFAULT 1,
  `max_crops` int(11) NOT NULL DEFAULT 1,
  `max_activities` int(11) NOT NULL DEFAULT 10,
  `max_transactions` int(11) NOT NULL DEFAULT 5,
  `max_employees` int(11) NOT NULL DEFAULT 1,
  `max_farms` int(11) NOT NULL DEFAULT 1,
  `max_team_members` int(11) NOT NULL DEFAULT 1,
  `season_analytics` tinyint(1) NOT NULL DEFAULT 0,
  `yield_suggestions` tinyint(1) NOT NULL DEFAULT 0,
  `cost_per_hectare` tinyint(1) NOT NULL DEFAULT 0,
  `payroll_tracking` tinyint(1) NOT NULL DEFAULT 0,
  `multiple_farms` tinyint(1) NOT NULL DEFAULT 0,
  `team_accounts` tinyint(1) NOT NULL DEFAULT 0,
  `custom_reports` tinyint(1) NOT NULL DEFAULT 0,
  `api_access` tinyint(1) NOT NULL DEFAULT 0,
  `data_retention_lifetime` tinyint(1) NOT NULL DEFAULT 1,
  `sync_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_tiers_visible` (`is_active`,`is_public`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- testimonials
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `testimonials`;
CREATE TABLE IF NOT EXISTS `testimonials` (
  `id` varchar(40) NOT NULL,
  `quote` text NOT NULL,
  `name` varchar(120) NOT NULL,
  `role` varchar(120) NOT NULL DEFAULT '',
  `initials` varchar(4) NOT NULL DEFAULT '',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- transactions
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `transactions`;
CREATE TABLE IF NOT EXISTS `transactions` (
  `id` varchar(40) NOT NULL,
  `farm_id` varchar(40) NOT NULL,
  `type` varchar(10) NOT NULL,
  `category` varchar(80) NOT NULL DEFAULT 'Other',
  `payment_status` varchar(20) NOT NULL DEFAULT 'paid',
  `amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `date` date NOT NULL,
  `description` varchar(255) NOT NULL DEFAULT '',
  `season` varchar(60) DEFAULT NULL,
  `field_id` varchar(40) DEFAULT NULL,
  `crop_field_id` varchar(40) DEFAULT NULL,
  `harvest_yield_id` varchar(40) DEFAULT NULL,
  `inventory_item_id` varchar(40) DEFAULT NULL,
  `source` varchar(20) NOT NULL DEFAULT 'manual',
  `created_by_id` varchar(40) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_tx_farm_date` (`farm_id`,`date`),
  KEY `idx_tx_farm_type` (`farm_id`,`type`),
  KEY `idx_tx_season` (`farm_id`,`season`),
  KEY `idx_tx_crop_field` (`crop_field_id`),
  KEY `fk_tx_field` (`field_id`),
  KEY `fk_tx_yield` (`harvest_yield_id`),
  KEY `fk_tx_creator` (`created_by_id`),
  KEY `fk_tx_inventory` (`inventory_item_id`),
  CONSTRAINT `fk_tx_creator` FOREIGN KEY (`created_by_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_tx_crop_field` FOREIGN KEY (`crop_field_id`) REFERENCES `crop_fields` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_tx_farm` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_tx_field` FOREIGN KEY (`field_id`) REFERENCES `fields` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_tx_inventory` FOREIGN KEY (`inventory_item_id`) REFERENCES `inventory_items` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_tx_yield` FOREIGN KEY (`harvest_yield_id`) REFERENCES `harvest_yields` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- users
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE IF NOT EXISTS `users` (
  `id` varchar(40) NOT NULL,
  `name` varchar(120) DEFAULT NULL,
  `email` varchar(190) NOT NULL,
  `password` varchar(255) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 0,
  `last_login_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_users_email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- weather_cache
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `weather_cache`;
CREATE TABLE IF NOT EXISTS `weather_cache` (
  `id` varchar(40) NOT NULL,
  `farm_id` varchar(40) NOT NULL,
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`data`)),
  `cached_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_weather_farm` (`farm_id`),
  CONSTRAINT `fk_weather_farm` FOREIGN KEY (`farm_id`) REFERENCES `farms` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- _migrations
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `_migrations`;
CREATE TABLE IF NOT EXISTS `_migrations` (
  `filename` varchar(191) NOT NULL,
  `applied_at` datetime NOT NULL,
  PRIMARY KEY (`filename`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
